"$MIMO_PYTHON" -c 'from docx import Document; from openpyxl import load_workbook; from pathlib import Path; p=Path("/documents");
for f in sorted(p.glob("*.docx")):
 print("\\n###",f.name); d=Document(f);
 for para in d.paragraphs:
  if para.text.strip(): print(para.text)
 for ti,t in enumerate(d.tables):
  print("[TABLE",ti,"]");
  for row in t.rows: print(" | ".join(c.text.replace("\\n"," / ") for c in row.cells))
f=next(p.glob("*.xlsx")); print("\\n###",f.name); w=load_workbook(f,data_only=True);
for s in w:
 print("[SHEET",s.title,s.max_row,s.max_column,"]");
 for row in s.iter_rows(values_only=True):
  if any(v is not None for v in row): print(" | ".join("" if v is None else str(v) for v in row))'

